// @ts-ignore Generated by `pnpm build:worker` at `.open-next/worker.js`. Absent before that build and present after, so @ts-expect-error cannot cover both.
import openNextWorker, { BucketCachePurge, DOQueueHandler, DOShardedTagCache } from './.open-next/worker.js'

import {
  applyQueueResults,
  buildWorkerRequest,
  type OpenNextWorkerModule,
  type QueueDispatchResult,
} from '@aikit/admin-jobs/worker'

export { BucketCachePurge, DOQueueHandler, DOShardedTagCache }

const openNextFetch: OpenNextWorkerModule['default']['fetch'] = openNextWorker.fetch

type WorkerEnv = {
  JOBS_INTERNAL_SECRET?: string
}

type QueueMessage = {
  ack: () => void
  body: unknown
  retry: () => void
}

type QueueBatch = {
  messages: QueueMessage[]
}

type ScheduledEvent = {
  cron: string
  scheduledTime: number
}

async function dispatch(
  kind: 'queue' | 'scheduled',
  payload: unknown,
  env: WorkerEnv,
  ctx: unknown,
): Promise<Response> {
  return openNextFetch(
    buildWorkerRequest({
      kind,
      payload,
      secret: env.JOBS_INTERNAL_SECRET,
    }),
    env,
    ctx,
  )
}

const worker = {
  fetch: (request: Request, env: WorkerEnv, ctx: unknown) => openNextFetch(request, env, ctx),

  async queue(batch: QueueBatch, env: WorkerEnv, ctx: unknown): Promise<void> {
    const response = await dispatch(
      'queue',
      { messages: batch.messages.map((message) => ({ body: message.body })) },
      env,
      ctx,
    )
    if (!response.ok) {
      batch.messages.forEach((message) => message.retry())
      return
    }
    const body = (await response.json()) as { results?: QueueDispatchResult[] }
    applyQueueResults(batch.messages, body.results ?? [])
  },

  async scheduled(event: ScheduledEvent, env: WorkerEnv, ctx: unknown): Promise<void> {
    const response = await dispatch(
      'scheduled',
      { cron: event.cron, scheduledTime: event.scheduledTime },
      env,
      ctx,
    )
    if (!response.ok) {
      const detail = await response.text()
      throw new Error(`Scheduled job run failed (${response.status}): ${detail.slice(0, 300)}`)
    }
  },
}

export default worker
